-    uint64_t       shift = 0;
-    const uint8_t *p     = buf;
+    uint64_t    k     = (uint8_t)((1 << prefix) - 1);
+    uint64_t    n     = 0;
+    uint64_t    add   = 0;
+    uint64_t    shift = 0;
+    uint8_t     byte;
+    unsigned    start_offset = offset;
+
+    byte = tvb_get_uint8(tvb, offset);

     if (out_flag) {
-        *out_flag = *p & (1 << prefix);
