-        *out_fin    = true;
+    if ((byte & k) != k) {
+        *out_result = byte & k;
         return 1;
     }

     n = k;

-    if (++p == end) {
-        *out_result = n;
-        *out_fin    = false;
-        return (int)(p - buf);
-    }
-
-    for (; p != end; ++p, shift += 7) {
-        add = (*p) & 0x7f;
+    for (++offset; tvb_captured_length_remaining(tvb, offset); ++offset, shift += 7) {
+        byte = tvb_get_uint8(tvb, offset);
+        add = byte & 0x7f;
         if (shift > HTTP3_QPACK_MAX_SHIFT) {
-            return -1;
+            return 0;
         }
         if ((HTTP3_QPACK_MAX_INT >> shift) < add) {
-            return -1;
+            return 0;
         }
         add <<= shift;
         if (HTTP3_QPACK_MAX_INT - add < n) {
-            return -1;
+            return 0;
         }

         n += add;

-        if (((*p) & (1 << 7)) == 0) {
+        if ((byte & (1 << 7)) == 0) {
